  ['MARK XXX','BLUE STEEL*','#4d667c','#b2c0c8','High-altitude',27,1.22,1.08,1.18],
  ['MARK XXXI','PYTHON*','#b67c39','#505866','Tracking systems',28,1.1,1.12,1.22],
